import Vue from 'vue';
import { IFreePlayData } from '../../types';
import { OPTIONS } from '../../options';

export default Vue.component('free-play', {
    name: 'FreePlay',
    props: {
        strings: { type: Object, required: true },
        isPortrait: { type: Boolean, required: true },
        deviceType: { type: String, required: true },
        onFreePlayMessage: { type: Function, required: true },
        onFreePlayEnded: { type: Function, required: true },
        onSettingsVisibilityChange: { type: Function, required: true },
        onFreePlayTAndCClicked: { type: Function, required: true },
        onCloseEndFreePlay: { type: Function, required: true },
        icon: { type: Function, required: true },
        theme: { type: Object, required: false, default: () => OPTIONS.theme }
    },
    computed: {
        headingColor(): string {
            return this.theme.textColour?.heading?.string ?? this.theme.darkAccent.string;
        },
        bodyColor(): string {
            return this.theme.textColour?.body?.string ?? '#000000';
        },
        primaryButtonStyle(): Record<string, string> {
            const shadowColor = this.theme.primaryButton?.boxShadowColour?.string;
            return {
                backgroundColor: this.theme.primaryButton?.backgroundColour?.string ?? this.theme.darkAccent.string,
                color: this.theme.primaryButton?.textColour?.string ?? '#FFFFFF',
                borderColor: this.theme.primaryButton?.outlineColour?.string ?? this.theme.darkAccent.string,
                boxShadow: shadowColor ? `0 4px 0 ${shadowColor}` : 'none'
            };
        }
    },
    data(): IFreePlayData {
        return {
            isVisible: false,
            inSettings: false,
            onDesktop: this.deviceType === 'desktop',
            onStartPage: true,
            headerText: '',
            awaitingResponse: false,
            startTitle: '',
            startContent: '',
            startContentMid: 'T&Cs Apply.',
            startContentEnd: 'Good Luck!',
            endTitle: '',
            endContentMid: '',
            endContentEnd: '',
            freePlayCount: 0,
            confirm: '',
            continueText: ''
        };
    },
    mounted(): void {
        this.onFreePlayMessage(this.onMessage, this);
        this.onFreePlayEnded(this.onEndMessage, this);
        this.onSettingsVisibilityChange(this.onSettingsVisibility, this);

        this.endTitle = this.strings.endTitle;
    },
    methods: {
        openTandCs(): void {
            this.onFreePlayTAndCClicked();
        },

        openGame(): void {
            this.isVisible = !this.isVisible;
        },

        closeEndFreePlay(): void {
            this.isVisible = !this.isVisible;
            this.onCloseEndFreePlay();
        },

        onSettingsVisibility(isVisible: boolean): void {
            this.inSettings = isVisible;
        },

        onMessage(data: number): void {
            this.isVisible = true;
            this.onStartPage = true;

            this.freePlayCount = data;

            if (data === 1) {
                this.startContent = this.strings.startContent.singular
                    .replace(/{{count}}/gi, data);
                this.startTitle = this.strings.startTitle.singular
                    .replace(/{{count}}/gi, data);
            } else {
                this.startContent = this.strings.startContent.plural
                    .replace(/{{count}}/gi, data);
                this.startTitle = this.strings.startTitle.plural
                    .replace(/{{count}}/gi, data);
            }

            this.startContentMid = this.strings.startContentMid
                .replace(/{{count}}/gi, data);
            this.startContentEnd = this.strings.startContentEnd
                .replace(/{{count}}/gi, data);

            this.confirm = this.strings.confirm;
        },

        onEndMessage(prize: number, payout: string): void {
            this.isVisible = true;
            this.onStartPage = false;

            if (prize > 0) {
                this.endContentMid = this.strings.endContentMid
                    .replace(/{{count}}/gi, payout);
            } else {
                this.endContentMid = '';
            }
            this.endContentEnd = this.strings.endContentEnd;
            this.continueText = this.strings.continue;
        }
    }
});